// Parser CSV mínimo (soporta comillas). Devuelve array de objetos usando la fila 1 como cabeceras.
const parseCsv = (texto) => {
  const filas = []; let fila = [], celda = '', dentro = false;
  const s = String(texto ?? '');
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (dentro) {
      if (c === '"' && s[i + 1] === '"') { celda += '"'; i++; }
      else if (c === '"') dentro = false;
      else celda += c;
    } else if (c === '"') dentro = true;
    else if (c === ',') { fila.push(celda); celda = ''; }
    else if (c === '\n') { fila.push(celda); filas.push(fila); fila = []; celda = ''; }
    else if (c !== '\r') celda += c;
  }
  if (celda !== '' || fila.length) { fila.push(celda); filas.push(fila); }
  const [cab, ...datos] = filas.filter((f) => f.some((x) => x !== ''));
  return (datos ?? []).map((f) => Object.fromEntries(cab.map((h, i) => [h.trim().toLowerCase(), (f[i] ?? '').trim()])));
};
const num = (v) => { const n = parseFloat(String(v).replace(',', '.')); return isFinite(n) ? n : 0; };

export const code = async (inputs) => {
  const base = inputs.entorno === 'produccion' ? 'https://api.tradier.com' : 'https://sandbox.tradier.com';
  const headers = { Authorization: 'Bearer ' + inputs.tradierToken, Accept: 'application/json' };
  const get = async (ruta) => (await fetch(base + ruta, { headers })).json();
  const hoy = new Date();
  const dias = (f) => Math.round((new Date(f + 'T21:00:00Z') - hoy) / 86400000);

  const posiciones = parseCsv(inputs.posicionesCsv);
  const libres = posiciones.filter((p) => num(p.acciones) >= 100 && String(p.call_abierto).toLowerCase() !== 'si');
  const lineas = [];

  for (const p of libres) {
    const ticker = String(p.ticker).toUpperCase();
    const costoBase = num(p.costo_base);
    try {
      const exp = await get('/v1/markets/options/expirations?symbol=' + ticker);
      const fechas = [].concat(exp?.expirations?.date ?? []);
      // Regla del sistema: vencimiento 30-45 DTE
      const fecha = fechas.find((f) => dias(f) >= 30 && dias(f) <= 45);
      if (!fecha) { lineas.push(ticker + ': sin vencimiento en la ventana 30-45 DTE.'); continue; }

      const cad = await get('/v1/markets/options/chains?symbol=' + ticker + '&expiration=' + fecha + '&greeks=true');
      const calls = [].concat(cad?.options?.option ?? []).filter((o) => o.option_type === 'call');
      // Reglas: delta 0.20-0.30, strike >= costo base, rendimiento del ciclo >= 0.5%
      const candidatos = calls
        .filter((o) => o.greeks && o.greeks.delta >= 0.20 && o.greeks.delta <= 0.30)
        .filter((o) => o.strike >= costoBase && o.bid > 0 && o.bid / costoBase >= 0.005)
        .sort((a, b) => b.bid / b.strike - a.bid / a.strike)
        .slice(0, 3);

      if (!candidatos.length) { lineas.push(ticker + ': ningun strike cumple las reglas este ciclo (no operar tambien es una decision).'); continue; }
      lineas.push(ticker + ' - vencimiento ' + fecha + ' (' + dias(fecha) + ' DTE):');
      for (const o of candidatos) {
        const rend = (o.bid / costoBase) * 100;
        const anual = rend * (365 / dias(fecha));
        lineas.push('  strike ' + o.strike + ' | delta ' + o.greeks.delta.toFixed(2) + ' | bid $' + o.bid.toFixed(2) +
          ' | ciclo ' + rend.toFixed(2) + '% | anualizado ' + anual.toFixed(1) + '%');
      }
    } catch (e) {
      lineas.push(ticker + ': error consultando datos (' + e.message + ').');
    }
  }

  const resumen = lineas.length
    ? 'Candidatos del ciclo (reglas: 30-45 DTE, delta 0.20-0.30, strike >= costo base, ciclo >= 0.5%):\n\n' + lineas.join('\n') +
      '\n\nAntes de vender: revisa earnings del periodo y verifica en la calculadora covered-calls/index.html.'
    : 'No hay acciones libres (100+ sin call abierto) este ciclo.';
  return { resumen, hayCandidatos: lineas.length > 0 };
};
